from __future__ import annotations
import sys
from importlib.machinery import ModuleSpec, PathFinder
from importlib.machinery import all_suffixes as module_suffixes
from importlib.util import spec_from_file_location
from itertools import chain
from pathlib import Path

MAPPING: dict[str, str] = {'assets': '/data/susvibes/assets', 'datasets': '/data/susvibes/datasets', 'evaluation_harness': '/data/susvibes/evaluation_harness', 'susvibes': '/data/susvibes/susvibes', 'tests': '/data/susvibes/tests'}
NAMESPACES: dict[str, list[str]] = {'assets': ['/data/susvibes/assets'], 'evaluation_harness': ['/data/susvibes/evaluation_harness'], 'datasets': ['/data/susvibes/datasets'], 'evaluation_harness.swe_agent': ['/data/susvibes/evaluation_harness/swe_agent'], 'evaluation_harness.openhands': ['/data/susvibes/evaluation_harness/openhands'], 'evaluation_harness.claude_code': ['/data/susvibes/evaluation_harness/claude_code'], 'evaluation_harness.gemini_cli': ['/data/susvibes/evaluation_harness/gemini_cli'], 'evaluation_harness.openhands.susvibes': ['/data/susvibes/evaluation_harness/openhands/susvibes'], 'evaluation_harness.openhands.susvibes.configs': ['/data/susvibes/evaluation_harness/openhands/susvibes/configs'], 'susvibes.strategies': ['/data/susvibes/susvibes/strategies'], 'susvibes.curate.adaptive_gen': ['/data/susvibes/susvibes/curate/adaptive_gen'], 'susvibes.curate.utils.agents.configs': ['/data/susvibes/susvibes/curate/utils/agents/configs'], 'susvibes.env_specs.default': ['/data/susvibes/susvibes/env_specs/default'], 'datasets.default': ['/data/susvibes/datasets/default'], 'datasets.default.examples': ['/data/susvibes/datasets/default/examples'], 'datasets.default.examples.psf__requests_74ea7cf7a6a27a4eeb2ae24e162bcc942a6706d5': ['/data/susvibes/datasets/default/examples/psf__requests_74ea7cf7a6a27a4eeb2ae24e162bcc942a6706d5'], 'datasets.default.examples.aio-libs__aiohttp-session_1b356f01bbab57d041c9a75bacd72fbbf8524728': ['/data/susvibes/datasets/default/examples/aio-libs__aiohttp-session_1b356f01bbab57d041c9a75bacd72fbbf8524728'], 'datasets.default.examples.django__django_07cefdee4a9d1fcd9a3a631cbd07c78defd1923b': ['/data/susvibes/datasets/default/examples/django__django_07cefdee4a9d1fcd9a3a631cbd07c78defd1923b'], 'datasets.default.examples.wagtail__wagtail_5c7a60977cba478f6a35390ba98cffc2bd41c8a4': ['/data/susvibes/datasets/default/examples/wagtail__wagtail_5c7a60977cba478f6a35390ba98cffc2bd41c8a4'], 'datasets.default.examples.buildbot__buildbot_e781f110933e05ecdb30abc64327a2c7c9ff9c5a': ['/data/susvibes/datasets/default/examples/buildbot__buildbot_e781f110933e05ecdb30abc64327a2c7c9ff9c5a']}
PATH_PLACEHOLDER = '__editable__.susvibes-0.1.0.finder' + ".__path_hook__"


class _EditableFinder:  # MetaPathFinder
    @classmethod
    def find_spec(cls, fullname: str, path=None, target=None) -> ModuleSpec | None:  # type: ignore
        # Top-level packages and modules (we know these exist in the FS)
        if fullname in MAPPING:
            pkg_path = MAPPING[fullname]
            return cls._find_spec(fullname, Path(pkg_path))

        # Handle immediate children modules (required for namespaces to work)
        # To avoid problems with case sensitivity in the file system we delegate
        # to the importlib.machinery implementation.
        parent, _, child = fullname.rpartition(".")
        if parent and parent in MAPPING:
            return PathFinder.find_spec(fullname, path=[MAPPING[parent]])

        # Other levels of nesting should be handled automatically by importlib
        # using the parent path.
        return None

    @classmethod
    def _find_spec(cls, fullname: str, candidate_path: Path) -> ModuleSpec | None:
        init = candidate_path / "__init__.py"
        candidates = (candidate_path.with_suffix(x) for x in module_suffixes())
        for candidate in chain([init], candidates):
            if candidate.exists():
                return spec_from_file_location(fullname, candidate)
        return None


class _EditableNamespaceFinder:  # PathEntryFinder
    @classmethod
    def _path_hook(cls, path) -> type[_EditableNamespaceFinder]:
        if path == PATH_PLACEHOLDER:
            return cls
        raise ImportError

    @classmethod
    def _paths(cls, fullname: str) -> list[str]:
        paths = NAMESPACES[fullname]
        if not paths and fullname in MAPPING:
            paths = [MAPPING[fullname]]
        # Always add placeholder, for 2 reasons:
        # 1. __path__ cannot be empty for the spec to be considered namespace.
        # 2. In the case of nested namespaces, we need to force
        #    import machinery to query _EditableNamespaceFinder again.
        return [*paths, PATH_PLACEHOLDER]

    @classmethod
    def find_spec(cls, fullname: str, target=None) -> ModuleSpec | None:  # type: ignore
        if fullname in NAMESPACES:
            spec = ModuleSpec(fullname, None, is_package=True)
            spec.submodule_search_locations = cls._paths(fullname)
            return spec
        return None

    @classmethod
    def find_module(cls, _fullname) -> None:
        return None


def install():
    if not any(finder == _EditableFinder for finder in sys.meta_path):
        sys.meta_path.append(_EditableFinder)

    if not NAMESPACES:
        return

    if not any(hook == _EditableNamespaceFinder._path_hook for hook in sys.path_hooks):
        # PathEntryFinder is needed to create NamespaceSpec without private APIS
        sys.path_hooks.append(_EditableNamespaceFinder._path_hook)
    if PATH_PLACEHOLDER not in sys.path:
        sys.path.append(PATH_PLACEHOLDER)  # Used just to trigger the path hook
